{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Diphemanil methylsulphate, a quaternary ammonium salt, showed very low oral bioavailability in healthy subjects; the query is also a permanent quaternary ammonium cation, directly supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "DX-9065a, a drug with strongly basic amidino groups, had human oral bioavailability of only 2–3% because of poor absorption of charged species; this supports low F for the similarly charged query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Propafenone, a basic amine with extensive first-pass metabolism, had mean oral bioavailability 18.6% with a range of 5–31%, mostly below the 20% threshold; its high transferability supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Acamprosate had about 11% oral bioavailability under fasting conditions due to poor absorption, supporting low F for a polar/charged query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Aspirin had absolute oral bioavailability of 65–75% in humans, a high-F example; however, this is outweighed by the multiple higher-transfer low-F analogues and the query's permanent cationic charge.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a permanently charged quaternary ammonium tropane ester. High-transfer evidence from quaternary ammonium (diphemanil), strongly basic amidine (DX-9065a), and first-pass metabolized basic amines (propafenone) consistently indicates low oral bioavailability, mostly below 20%. The few high-F examples such as aspirin are mechanistically distinct and outweighed. Therefore predict low F (<20%).",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the exact query molecule.",
    "No exact analogue with the same N-ethyl-N-methyl-scopolamine scaffold; extrapolation relies on charged ammonium and basic amine analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

